/* BlipVibe full-skin engine styles. Active only under body.fs (see js/fullskins.js).
 * Asset URLs arrive as --fs-* custom properties set on <body>, so nothing downloads until a
 * full skin is applied. Many rules need !important because existing premium/mobile rules use it
 * and some surfaces get inline styles from JS (documented in the engine spec). */

/* ---------- page + typography ---------- */
body.fs {
  /* the skin background is painted by the fixed #premiumBgLayer below, not here: iOS ignores
     background-attachment:fixed and would stretch it over the whole page (blurry) */
  background: #d9c7b3 !important;
  color: var(--fs-ink) !important;
  font-family: var(--fs-font);
}
body.fs::before { background: transparent !important; }
/* the user's custom premium background photo + overlay give way to the skin's own background */
body.fs #premiumBgLayer {
  display: block !important;
  background: var(--fs-background) center / cover no-repeat !important;
  filter: none !important;
}
body.fs #premiumBgOverlay,
body.fs #premiumBgDarkness { display: none !important; }
/* shop logos give way to the skin's wordmark */
body.fs .nav-logo .nav-logo-img { display: none !important; }
body.fs .nav-logo.nav-logo-image::after { content: "BlipVibe"; }
body.fs .page,
body.fs .main-container,
body.fs .center-feed { background: transparent !important; }
body.fs h1, body.fs h2, body.fs h3, body.fs h4,
body.fs .nav-logo, body.fs .profile-name, body.fs .post-username, body.fs .card-heading {
  font-family: var(--fs-title-font);
  color: var(--fs-ink) !important;
}
body.fs p, body.fs span, body.fs .post-time, body.fs .stat-label,
body.fs .profile-title, body.fs .profile-about { color: inherit; }
body.fs .post-time, body.fs .stat-label, body.fs .quest-progress,
body.fs .quest-reset, body.fs .profile-title { color: var(--fs-muted) !important; }

/* ---------- stretchable surfaces (9-slice panels from the kit) ---------- */
body.fs .card,
body.fs .feed-post,
body.fs .modal-content,
body.fs .user-dropdown,
body.fs .post-dropdown,
body.fs .quest-panel,
body.fs .coin-goal-bar,
body.fs .featured-skin-banner,
body.fs .msg-contact,
body.fs .notif-item,
body.fs .group-card,
body.fs .comment-item {
  background: transparent !important;
  box-shadow: none !important;
  border: 16px solid transparent !important;
  border-image-source: var(--fs-panel-card) !important;
  border-image-slice: calc(var(--fs-slice) * 1%) fill !important;
  border-image-width: var(--fs-edge, 16px) !important;
  border-image-repeat: round !important;
  border-radius: 0 !important;
  color: var(--fs-ink) !important;
}
body.fs .card:hover,
body.fs .msg-contact.active,
body.fs .notif-item.unread { border-image-source: var(--fs-panel-card-active) !important; }

/* featured-skin banner text comes with the featured skin's own inline colours */
body.fs .featured-skin-banner h4,
body.fs .featured-skin-banner [style*="color"] { color: var(--fs-ink) !important; }
body.fs .featured-skin-banner p { color: var(--fs-muted) !important; }

/* panels the app leaves empty (e.g. coin goal with infinite coins) shouldn't draw a blank card */
body.fs .coin-goal-bar:empty,
body.fs .featured-skin-banner:empty,
body.fs .quest-panel:empty { display: none !important; }

/* story create/view screens are full-bleed media: no panel frame, keep their own dark styling */
body.fs .modal-content:has(.story-create-wrap, .story-canvas-full, .story-content, .story-progress) {
  border: 0 !important;
  border-image: none !important;
  background: #000 !important;
  color: #fff !important;
}
body.fs .modal-content:has(.story-create-wrap, .story-canvas-full, .story-content, .story-progress) :is(h1, h2, h3, h4, p, span) {
  color: #fff !important;
}

/* ---------- tabs / chips ---------- */
body.fs .search-tab {
  text-shadow: none !important;
  background: transparent !important;
  border: 10px solid transparent !important;
  border-image: var(--fs-chip) 30% fill / 10px round !important;
  border-radius: 0 !important;
  color: var(--fs-ink) !important;
  box-shadow: none !important;
}
body.fs .search-tab.active {
  border-image-source: var(--fs-chip-active) !important;
  color: var(--fs-ink) !important;
  font-weight: 700;
}

/* ---------- buttons ---------- */
body.fs .btn-primary,
body.fs .featured-buy-btn,
body.fs .join-group-btn {
  background: transparent !important;
  border: 12px solid transparent !important;
  border-image: var(--fs-btn-primary) 30% fill / 12px round !important;
  border-radius: 0 !important;
  color: var(--fs-ink) !important;
  box-shadow: none !important;
}
body.fs-dark .btn-primary { color: #fff !important; }
body.fs .btn-outline,
body.fs .btn-disabled {
  background: transparent !important;
  border: 12px solid transparent !important;
  border-image: var(--fs-btn-secondary) 30% fill / 12px round !important;
  border-radius: 0 !important;
  color: var(--fs-ink) !important;
}

/* ---------- top navbar ---------- */
body.fs .navbar {
  background: var(--fs-header-bar) center / 100% 100% no-repeat !important;
  box-shadow: none !important;
  border: 0 !important;
}
body.fs .nav-logo { color: var(--fs-ink) !important; }
body.fs .nav-coins,
body.fs .nav-coins .coin-count { color: var(--fs-ink) !important; }

/* ---------- image icons (replace Font Awesome glyphs) ---------- */
body.fs .fs-ico,
body.fs .nav-link[data-page] > i,
body.fs .mobile-search-btn > i,
body.fs .mobile-notif-btn > i,
body.fs .nav-music-btn > i,
body.fs .nav-coins > i,
body.fs .action-btn > i:is(.fa-thumbs-up, .fa-thumbs-down, .fa-face-smile, .fa-comment, .fa-share-from-square, .fa-share),
body.fs .avatar-edit-btn > i,
body.fs .timeline-cover-btn > i {
  display: inline-block !important;
  width: 1.45em; height: 1.45em;
  background: center / contain no-repeat;
  color: transparent !important;
  vertical-align: middle;
}
body.fs .nav-link[data-page] > i::before,
body.fs .mobile-search-btn > i::before,
body.fs .mobile-notif-btn > i::before,
body.fs .nav-music-btn > i::before,
body.fs .nav-coins > i::before,
body.fs .action-btn > i:is(.fa-thumbs-up, .fa-thumbs-down, .fa-face-smile, .fa-comment, .fa-share-from-square, .fa-share)::before,
body.fs .avatar-edit-btn > i::before,
body.fs .timeline-cover-btn > i::before { content: "" !important; }
body.fs .nav-link[data-page="home"] > i { background-image: var(--fs-icon-home); }
body.fs .nav-link[data-page="groups"] > i { background-image: var(--fs-icon-groups); }
body.fs .nav-link[data-page="shop"] > i { background-image: var(--fs-icon-skins); }
body.fs .nav-link[data-page="profiles"] > i { background-image: var(--fs-icon-network); }
body.fs .nav-link[data-page="messages"] > i { background-image: var(--fs-icon-messages); }
body.fs .nav-link[data-page="notifications"] > i,
body.fs .mobile-notif-btn > i { background-image: var(--fs-icon-bell); }
body.fs .mobile-search-btn > i { background-image: var(--fs-icon-search); }
body.fs .nav-music-btn > i { background-image: var(--fs-icon-music); }
body.fs .nav-coins > i { background-image: var(--fs-icon-coin); }
body.fs .action-btn > i.fa-thumbs-up { background-image: var(--fs-icon-like); }
body.fs .action-btn > i.fa-thumbs-down { background-image: var(--fs-icon-dislike); }
body.fs .action-btn > i.fa-face-smile { background-image: var(--fs-icon-emoji); }
body.fs .action-btn > i.fa-comment { background-image: var(--fs-icon-comment); }
body.fs .action-btn > i:is(.fa-share-from-square, .fa-share) { background-image: var(--fs-icon-share); }
body.fs .action-btn > i { color: var(--fs-ink); }
body.fs .avatar-edit-btn > i,
body.fs .timeline-cover-btn > i { background-image: var(--fs-icon-camera); }
body.fs .action-btn { color: var(--fs-ink) !important; }
/* liked / disliked (owner audit, Nov 16: "if you liked or disliked it, it should fill or change"): every full skin swaps
   in its painted ON icon. Feeds mark it two ways (.liked/.disliked on the button, or only a solid .fas icon), so catch
   both. Skins without ON art fall back to their OFF icon with a glow. A quick pop plays when it turns on. */
body.fs :is(.like-btn.liked, .like-btn:has(> i.fas)) > i { background-image: var(--fs-icon-like-on, var(--fs-icon-like)); animation: fsLikePop .32s cubic-bezier(.3,1.6,.5,1); }
body.fs :is(.dislike-btn.disliked, .dislike-btn:has(> i.fas)) > i { background-image: var(--fs-icon-dislike-on, var(--fs-icon-dislike)); animation: fsLikePop .32s cubic-bezier(.3,1.6,.5,1); }
@keyframes fsLikePop { 0% { transform: scale(.7); } 60% { transform: scale(1.25); } 100% { transform: scale(1); } }

/* ---------- bottom nav (mobile) ---------- */
@media (max-width: 768px) {
  body.fs .nav-center {
    background: var(--fs-nav-bar) center / 100% 100% no-repeat !important;
    border: 0 !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
  }
  body.fs .nav-center .nav-link { color: var(--fs-ink) !important; background: transparent !important; }
  body.fs .nav-center .nav-link.active {
    background: var(--fs-nav-active) center / 100% 100% no-repeat !important;
    color: var(--fs-ink) !important;
  }
  body.fs .nav-center .nav-link > i { width: 28px !important; min-width: 28px; height: 28px !important; flex-shrink: 0; }
}

/* ---------- avatars: skin shape (mask) ---------- */
body.fs #profileAvatarImg,
body.fs .modal-profile-top img,
body.fs .pv-profile-card .profile-avatar,
body.fs .nav-avatar,
body.fs .post-create-avatar {
  border-radius: 0 !important;
  border: 0 !important;
  -webkit-mask: var(--fs-avatar-mask) center / contain no-repeat;
  mask: var(--fs-avatar-mask) center / contain no-repeat;
}
body.fs .profile-avatar-wrap::before { display: none !important; }
body.fs .profile-avatar-wrap {
  background: transparent !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  border: 0 !important;
}
body.fs .profile-avatar-wrap::after {
  content: "";
  position: absolute; inset: -5%;
  background: var(--fs-avatar-frame) center / contain no-repeat;
  pointer-events: none;
  z-index: 2;
}
body.fs .profile-avatar-wrap { position: relative; }

/* ---------- quests (state image chosen by js: data-fs-q = 0 | 50 | 100) ---------- */
body.fs .quest-icon {
  background: var(--fs-quest-0) center / contain no-repeat !important;
  width: 44px !important; height: 44px !important;
  border-radius: 0 !important;
}
body.fs .quest-icon > i { display: none !important; }
body.fs .quest-item[data-fs-q="50"] .quest-icon { background-image: var(--fs-quest-50) !important; }
body.fs .quest-item[data-fs-q="100"] .quest-icon { background-image: var(--fs-quest-100) !important; }
body.fs .quest-item { border-color: rgba(0, 0, 0, .1) !important; }
body.fs .quest-bar { background: rgba(0, 0, 0, .12) !important; }
body.fs .quest-bar-fill { background: var(--fs-accent) !important; }
body.fs .quest-reward,
body.fs .quest-reward i { color: var(--fs-ink) !important; }

/* ---------- profile card text, stats, links ---------- */
body.fs .stat-count { color: var(--fs-ink) !important; }
body.fs .profile-stats { border-color: transparent !important; }
body.fs .view-profile-link,
body.fs .pv-back-link,
body.fs .profile-website { color: var(--fs-muted) !important; }
body.fs .coin-goal-bar p strong { color: var(--fs-accent) !important; }
body.fs .coin-goal-track { background: rgba(0, 0, 0, .12) !important; }
body.fs .coin-goal-fill { background: var(--fs-accent) !important; }

/* ---------- round photo buttons (cover / avatar camera) ---------- */
body.fs .timeline-cover-btn,
body.fs .avatar-edit-btn {
  background: var(--fs-btn-round) center / contain no-repeat !important;
  border: 0 !important;
  box-shadow: none !important;
  color: var(--fs-ink) !important;
  z-index: 5 !important;
}
body.fs .timeline-cover-btn > i,
body.fs .avatar-edit-btn > i { width: 18px !important; height: 18px !important; }

/* ---------- timeline (cover) photos rendered by js ---------- */
body.fs #timelineCover,
body.fs #pvCoverBanner {
  background-image: none !important;
  background-color: transparent !important;
  position: relative;
  overflow: visible;
}
.fs-timeline { position: absolute; inset: 0; pointer-events: none; z-index: 1; }
.fs-tl-slot { position: absolute; }
.fs-tl-slot img { display: block; width: 100%; height: 100%; object-fit: cover; }
.fs-tl-empty::before { content: ""; display: block; width: 100%; height: 100%; background: rgba(0, 0, 0, .06); }

/* post photos: the app letterboxes portrait images on black — let the skin's frame show instead */
body.fs .pm-thumb img,
body.fs .pm-thumb video { background: transparent !important; }

/* ================================================================
   SCRAPBOOK (owner's master) — every visual is kit art; CSS only places it
   ================================================================ */

/* timeline: the kit's polaroid pair (lace + flower) with your photos behind its two windows.
   Window boxes measured from timeline-frame.webp (872x848): centre, size and tilt of each. */
body.fs-scrapbook .fs-timeline {
  inset: auto;
  left: 50%; top: -2%;
  transform: translateX(-50%);
  width: min(84%, 330px);
  aspect-ratio: 872 / 848;
}
body.fs-scrapbook .fs-timeline::after {
  content: "";
  position: absolute; inset: 0;
  background: var(--fs-timeline-frame) center / 100% 100% no-repeat;
  pointer-events: none;
}
body.fs-scrapbook .fs-tl-slot-1 { left: 3.9%; top: 9.9%; width: 46.9%; height: 47%; transform: rotate(-13.3deg); }
body.fs-scrapbook .fs-tl-slot-2 { left: 46.6%; top: 23.7%; width: 46.1%; height: 46.7%; transform: rotate(11.6deg); }
body.fs-scrapbook .fs-tl-slot img { filter: sepia(.15) saturate(.92); }
body.fs-scrapbook .fs-tl-empty::before { background: var(--fs-panel-card) center / cover no-repeat; }
body.fs-scrapbook .profile-card .profile-cover { display: none !important; }
body.fs-scrapbook #pvCoverBanner { min-height: 250px; }

/* profile view: no big panel — torn name label, torn stats strip, torn Edit button (master) */
body.fs-scrapbook :is(.pv-profile-card, #profileCard) {
  border: 0 !important;
  border-image: none !important;
  background: transparent !important;
}
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-cover { display: none !important; }
/* name + status share one torn label; badges, bio etc. follow it (real cards add a badge row
   between them) */
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-info { display: flex; flex-direction: column; align-items: center; }
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-info > * { order: 2; }
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-info > .profile-avatar-wrap,
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-info > .profile-name,
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-info > .profile-title { order: 0; }
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-info > .badge-row,
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-info > .profile-about,
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-info > .profile-website { order: 1; margin-bottom: 12px; }
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-stats,
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .pv-actions { align-self: stretch; }
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-name {
  display: block;
  width: 72%;
  margin: 14px auto 0;
  padding: 0 0 26px;
  font-size: 34px !important;
  border: var(--fs-edge) solid transparent;
  border-image: var(--fs-btn-secondary) 16.67% fill / var(--fs-edge) round;
}
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-info:not(:has(> .profile-title)) > .profile-about { order: 0; }
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-info:not(:has(> .profile-title)) > .profile-about,
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-title {
  position: relative;
  margin-top: -38px;
  margin-bottom: 22px;
  font-size: 17px !important;
}
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-stats {
  width: 90%;
  margin: 0 auto 16px;
  padding: 0;
  border: var(--fs-edge) solid transparent;
  border-image: var(--fs-btn-secondary) 16.67% fill / var(--fs-edge) round;
  display: flex !important; flex-wrap: nowrap !important;
}
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-stats > .stat { flex: 1 1 0; min-width: 0; }
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .stat-count { font-family: var(--fs-title-font); font-size: 30px !important; }
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .stat-label { color: var(--fs-ink) !important; font-size: 16px !important; }
body.fs-scrapbook #pvEditProfileBtn {
  display: flex !important;
  align-items: center;
  margin: 0 auto;
  width: 80%;
  justify-content: center;
  flex-direction: row-reverse;
  gap: 14px;
  font-family: var(--fs-title-font);
  font-size: 22px !important;
  border-image-source: var(--fs-btn-secondary) !important;
}

/* header: paperclip clipped over the logo (master) */
body.fs-scrapbook .navbar::before {
  content: "";
  position: absolute; left: -20px; top: 6px;
  width: 56px; height: 30px;
  background: var(--fs-deco-5) center / contain no-repeat;
  transform: rotate(-62deg);
  z-index: 3;
  pointer-events: none;
}

/* quest card: spiral binding, pink paper icon tiles, paper progress bars, torn dividers, bow */
body.fs-scrapbook .quest-panel { position: relative; padding-left: 26px !important; overflow: visible !important; }
body.fs-scrapbook .quest-panel::before {
  content: "";
  position: absolute; left: -18px; top: 8px; bottom: 8px; width: 34px;
  background: var(--fs-deco-6) center / 100% 100% no-repeat;
  pointer-events: none;
}
body.fs-scrapbook .quest-panel::after {
  content: "";
  position: absolute; right: -12px; bottom: -22px; width: 74px; height: 64px;
  background: var(--fs-deco-2) center / contain no-repeat;
  transform: rotate(8deg);
  pointer-events: none;
}
body.fs-scrapbook .quest-icon,
body.fs-scrapbook .quest-item[data-fs-q] .quest-icon {
  background: var(--fs-tile) center / 100% 100% no-repeat !important;
  width: 34px !important; height: 34px !important;
  border-radius: 0 !important;
}
body.fs-scrapbook .quest-icon > i { display: inline-block !important; color: #7b3f4c !important; font-size: 14px; }
body.fs-scrapbook .quest-item {
  border: 0 !important;
  background: var(--fs-divider) center bottom / 92% 5px no-repeat;
}
body.fs-scrapbook .quest-item:last-child { background: none; }

/* progress bars (quests + coin goal): paper track + rose fill, ends kept round by 9-slicing */
body.fs-scrapbook .quest-bar,
body.fs-scrapbook .coin-goal-track {
  background: transparent !important;
  border: 5px solid transparent !important;
  border-image: var(--fs-bar-track) 35 36 fill / 5px stretch !important;
  border-radius: 0 !important;
  height: 12px !important;
  overflow: visible !important;
  box-sizing: border-box;
}
body.fs-scrapbook .quest-bar-fill,
body.fs-scrapbook .coin-goal-fill {
  background: transparent !important;
  border: 5px solid transparent;
  border-image: var(--fs-bar-fill) 35 36 fill / 5px stretch;
  border-radius: 0 !important;
  margin: -5px;
  height: 12px !important;
  min-width: 12px;
  box-sizing: border-box;
}
body.fs-scrapbook .quest-bar-fill[style*="width:0%"],
body.fs-scrapbook .quest-bar-fill[style*="width: 0%"] { display: none; }

/* text fields: the kit's paper strip */
body.fs-scrapbook .post-input-fake,
body.fs-scrapbook .post-input,
body.fs-scrapbook .page-search,
body.fs-scrapbook .search-bar,
body.fs-scrapbook #msgInput,
body.fs-scrapbook .msg-search,
body.fs-scrapbook .comment-input,
body.fs-scrapbook .cpm-textarea,
body.fs-scrapbook #searchPageInput {
  background: var(--fs-field) center / 100% 100% no-repeat !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

/* stories: the kit's avatar frame instead of the gradient ring */
body.fs-scrapbook .story-ring,
body.fs-scrapbook .story-add .story-ring {
  background: var(--fs-avatar-frame) center / 100% 100% no-repeat !important;
  padding: 4px !important;
}
body.fs-scrapbook .story-ring img { border: 0 !important; }

/* posts: photo in the kit's polaroid frame with washi tape, a paper heart and a lavender sprig */
body.fs-scrapbook .post-media-grid { position: relative; overflow: visible !important; }
body.fs-scrapbook .post-media-grid .pm-thumb {
  position: relative;
  overflow: visible !important;
  background: transparent !important;
  border-style: solid !important;
  border-color: transparent !important;
  border-width: 12px 14px 38px 12px !important;
  border-image: var(--fs-photo-frame) 44 49 137 40 fill / 12px 14px 38px 12px round !important;
  border-radius: 0 !important;
  transform: rotate(-1.2deg);
}
body.fs-scrapbook .post-media-grid .pm-thumb:nth-child(even) { transform: rotate(1.4deg); }
body.fs-scrapbook .post-media-grid .pm-thumb img,
body.fs-scrapbook .post-media-grid .pm-thumb video {
  border-radius: 0 !important;
  width: 100% !important; height: 100% !important; max-height: 100% !important;
  object-fit: cover !important;
}
body.fs-scrapbook .post-media-grid .pm-thumb::before {
  content: "";
  position: absolute; top: -24px; left: 50%;
  width: 92px; height: 26px;
  background: var(--fs-deco-4) center / 100% 100% no-repeat;
  transform: translateX(-50%) rotate(-4deg);
  z-index: 2;
  pointer-events: none;
}
body.fs-scrapbook .post-media-grid .pm-thumb:nth-child(even)::before { background-image: var(--fs-tape-2); transform: translateX(-50%) rotate(5deg); }
body.fs-scrapbook .post-media-grid::after {
  content: "";
  position: absolute; top: -16px; right: -12px;
  width: 46px; height: 42px;
  background: var(--fs-deco-3) center / contain no-repeat;
  transform: rotate(14deg);
  z-index: 3;
  pointer-events: none;
}
body.fs-scrapbook .post-media-grid::before {
  content: "";
  position: absolute; left: -16px; bottom: -6px;
  width: 30px; height: 92px;
  background: var(--fs-deco-1) center / contain no-repeat;
  transform: rotate(-10deg);
  z-index: 3;
  pointer-events: none;
}

/* page titles sit on a torn paper label (master: Groups / Messages / Skins headers) */
body.fs-scrapbook .page-header h2,
