body.fs .page-subtitle { color: var(--fs-muted) !important; }
body.fs .connections-col { background: transparent !important; box-shadow: none !important; border-color: transparent !important; }

/* create post: the kit's thicker buttons need the footer to wrap; keep the counter on one line */
body.fs .cpm-footer { flex-wrap: wrap; row-gap: 6px; }
body.fs #cpmCharCounter { white-space: nowrap; flex-shrink: 0; width: 100%; text-align: right; color: var(--fs-muted) !important; }

/* "Earn coins" sidebar chips */
