  position: absolute; right: 6%; top: 6%;
  width: 30px; height: 30px;
  background: var(--fs-icon-camera) center / 55% no-repeat, var(--fs-btn-round) center / contain no-repeat;
  z-index: 3; pointer-events: none;
}

/* ================================================================
   SCRAPBOOK SPACING — measured from the owner's master at phone scale:
   cards/rows ~8pt from the screen edge, 8-10pt gaps, thin torn edges, compact rows
   ================================================================ */
@media (max-width: 768px) {
  body.fs-scrapbook .card,
  body.fs-scrapbook .feed-post,
  body.fs-scrapbook .quest-panel,
  body.fs-scrapbook .coin-goal-bar,
  body.fs-scrapbook .featured-skin-banner,
  body.fs-scrapbook .msg-contact,
  body.fs-scrapbook .notif-item,
  body.fs-scrapbook .group-card,
  body.fs-scrapbook .profile-card-item {
    border-width: 12px !important;
    margin-bottom: 8px !important;
  }
  body.fs-scrapbook .main-container,
  body.fs-scrapbook .page-container { padding-left: 8px !important; padding-right: 8px !important; }
  body.fs-scrapbook .center-feed { gap: 0 !important; }
  /* message / people / group rows: compact like the concept (~84pt tall, 64pt avatars) */
  body.fs-scrapbook .msg-contact { padding: 0 4px !important; min-height: 72px; align-items: center; }
  body.fs-scrapbook .msg-contact img, body.fs-scrapbook .msg-contact .msg-contact-avatar { width: 56px !important; height: 56px !important; }
  body.fs-scrapbook .msg-contact-name { font-family: var(--fs-title-font); font-size: 20px !important; }
  body.fs-scrapbook .msg-contact-list { padding-left: 0 !important; padding-right: 0 !important; }

  /* every page keeps the app's top bar (the concepts leave it out, the app never does — owner Nov 15);
     page content starts just under the banner, page titles centred */
  body.fs-scrapbook .page.active { padding-top: calc(62px + env(safe-area-inset-top, 0px)) !important; }
  body.fs-scrapbook .page-header { text-align: center; }
  body.fs-scrapbook .page-header h2,
  body.fs-scrapbook .msg-sidebar-header h3 { display: table !important; margin: 0 auto 8px !important; }
  body.fs-scrapbook .msg-sidebar-header { padding: 0 0 6px !important; text-align: center; }
}
body.fs .msg-contact-name { color: var(--fs-ink) !important; }
body.fs .msg-contact-preview, body.fs .msg-contact-time { color: var(--fs-muted) !important; }
/* concept: body text is ink, never the accent colour */
body.fs .quest-info p, body.fs .quest-info p strong { color: var(--fs-ink) !important; }
body.fs .group-card-body p, body.fs .group-card-body h4 { color: var(--fs-ink) !important; }
body.fs .post-menu-btn, body.fs .post-menu-btn i { color: var(--fs-ink) !important; }
body.fs .notif-text p { color: var(--fs-ink) !important; }
body.fs .notif-text span { color: var(--fs-muted) !important; }
@media (max-width: 768px) {
  body.fs-scrapbook .notif-item { padding: 0 4px !important; min-height: 60px; }
  /* skins grid cards: Buy is the button, Try On a small link under it — keeps every card the same height */
  body.fs-scrapbook .fsk-body .shop-card-actions { flex-direction: column-reverse !important; gap: 2px !important; }
  body.fs-scrapbook .fsk-body .try-on-btn {
    border: 0 !important; border-image: none !important; background: none !important;
    height: auto !important; font-size: 11px !important; text-decoration: underline; color: var(--fs-muted) !important;
  }
  body.fs-scrapbook .fsk-body .skin-price { font-size: 11px !important; }
}
/* modal dividers: torn paper strip instead of a CSS line */
body.fs-scrapbook .modal-header,
body.fs-scrapbook .cpm-footer,
body.fs-scrapbook .cpm-header {
  border-color: transparent !important;
}
body.fs-scrapbook .modal-header { background: var(--fs-divider) center bottom / 94% 5px no-repeat !important; }
body.fs-scrapbook .cpm-footer { background: var(--fs-divider) center top / 94% 5px no-repeat !important; }

/* ================================================================
   SCRAPBOOK set 3 — textured banner, nav bar, crumpled rows, chips, coin tag, avatar ring
   ================================================================ */
/* banner: the full-width torn pink strip (art spans the screen; bottom edge deckled) */
body.fs-scrapbook .navbar {
  border: 0 !important; border-image: none !important;
  background: var(--fs-banner) center bottom / 100% 100% no-repeat !important;
  height: calc(70px + env(safe-area-inset-top, 0px)) !important;
  max-height: calc(70px + env(safe-area-inset-top, 0px)) !important;
}
/* coin balance on the paper tag; header avatar in the paper ring */
body.fs-scrapbook .nav-coins {
  background: transparent !important; border: 8px solid transparent !important; border-radius: 0 !important;
  border-image: var(--fs-coin-pill) 70 fill / 10px round !important; padding: 0 4px !important;
}
body.fs-scrapbook .nav-user { position: relative; }
body.fs-scrapbook .nav-user::after {
  content: ""; position: absolute; left: 50%; top: 50%; width: 46px; height: 46px; transform: translate(-50%, -50%);
  background: var(--fs-avatar-ring) center / contain no-repeat; pointer-events: none;
}
body.fs-scrapbook .nav-user .nav-username, body.fs-scrapbook .nav-user > i { display: none !important; }
/* bottom nav: the textured torn strip, full width */
@media (max-width: 768px) {
  body.fs-scrapbook .nav-center {
    border: 0 !important; border-image: none !important;
    background: var(--fs-navbar) center top / 100% 100% no-repeat !important;
    padding-top: 14px !important;
  }
}
/* list rows (Messages, Groups, Network, Search, Notifications): crumpled paper like the concept */
body.fs-scrapbook .msg-contact,
body.fs-scrapbook #groupsSections .group-card,
body.fs-scrapbook #page-profiles .profile-card-item,
body.fs-scrapbook #page-search .profile-card-item,
body.fs-scrapbook .notif-item {
  border-image-source: var(--fs-row9-crumpled) !important;
  border-image-slice: 90 100 fill !important;
  border-image-width: 14px 16px !important;
}
/* tabs / chips: textured paper tags */
body.fs-scrapbook .search-tab { border-image-source: var(--fs-chip9) !important; border-image-slice: 60 fill !important; }
body.fs-scrapbook .search-tab.active { border-image-source: var(--fs-chip9-active) !important; }
@media (max-width: 768px) {
  body.fs-scrapbook .msg-contact-list { gap: 0 !important; }
  body.fs-scrapbook .msg-contact { margin: 0 0 4px !important; }
  body.fs-scrapbook #groupsSections .shop-scroll-row { gap: 4px !important; }
  body.fs-scrapbook .connections-grid, body.fs-scrapbook #page-search .page-grid { gap: 4px !important; }
}
/* back-to-top button on the kit's round paper button */
body.fs #scrollToTopBtn {
  background: var(--fs-btn-round) center / contain no-repeat !important;
  color: var(--fs-ink) !important; box-shadow: none !important; border: 0 !important;
}

/* ================================================================
   SCRAPBOOK set 4 — soft paper, built against the owner's post / messages / chat crops
   ================================================================ */
/* list rows: soft paper (set 3's crumpled was too wrinkled) */
body.fs-scrapbook .msg-contact,
body.fs-scrapbook #groupsSections .group-card,
body.fs-scrapbook #page-profiles .profile-card-item,
body.fs-scrapbook #page-search .profile-card-item,
body.fs-scrapbook .notif-item {
  border-image-source: var(--fs-row9-soft) !important;
  border-image-slice: 80 100 fill !important;
  border-image-width: 14px 16px !important;
}
/* labels (page titles, profile name, stats strip, subtitles, section headings): torn paper tag */
body.fs-scrapbook .page-header h2,
body.fs-scrapbook .msg-sidebar-header h3,
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-name,
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-stats,
body.fs-scrapbook .page-subtitle,
body.fs-scrapbook .connections-heading {
  border-image: var(--fs-label9) 70 fill / 12px round !important;
}
/* unread marker: the kit's rose dot instead of a count pill */
body.fs-scrapbook .msg-contact-name span[style*="border-radius:10px"] {
  display: inline-block; width: 12px; height: 12px; padding: 0 !important; margin-left: 8px !important;
  font-size: 0 !important; vertical-align: middle;
  background: var(--fs-unread-dot) center / contain no-repeat !important;
}

/* POST (concept-post): soft card, tape on the card's corner, name with the time under it,
   landscape photo on a soft deckled mat, compact action row */
body.fs-scrapbook .feed-post { position: relative; overflow: visible !important; }
body.fs-scrapbook .feed-post::before {
  content: ""; position: absolute; left: -14px; top: -10px; width: 74px; height: 24px;
  background: var(--fs-tape-card) center / 100% 100% no-repeat; transform: rotate(-24deg);
  z-index: 4; pointer-events: none;
}
body.fs-scrapbook .post-user-top { flex-direction: column !important; align-items: flex-start !important; gap: 0 !important; }
body.fs-scrapbook .post-username { font-size: 19px !important; line-height: 1.1; }
body.fs-scrapbook .post-time { font-size: 13px !important; }
body.fs-scrapbook .post-header img.post-avatar,
body.fs-scrapbook .post-header .post-avatar { width: 44px !important; height: 44px !important; }
body.fs-scrapbook .post-media-grid.pm-count-1 { height: auto !important; aspect-ratio: 4 / 3; }
body.fs-scrapbook .post-media-grid .pm-thumb {
  transform: none !important;
  border-width: 8px !important;
  border-image: var(--fs-photo-soft-edge) 90 fill / 10px round !important;
}
body.fs-scrapbook .post-media-grid .pm-thumb:nth-child(even) { transform: none !important; }
body.fs-scrapbook .post-media-grid .pm-thumb::before { display: none !important; }
body.fs-scrapbook .post-actions { padding: 6px 4px 0 !important; border: 0 !important; }
body.fs-scrapbook .post-actions .action-left { width: 100%; justify-content: space-between; }
body.fs-scrapbook .action-btn.liked > i { filter: none; }

/* CHAT (concept-chat): torn-note bubbles, plain header on the page, soft paper input bar,
   rose round send button, hand-drawn heart */
body.fs-scrapbook .msg-chat-header { background: none !important; border: 0 !important; }
body.fs-scrapbook .msg-chat-header h4 { font-family: var(--fs-title-font); font-size: 22px !important; color: var(--fs-ink) !important; }
body.fs-scrapbook .msg-bubble {
  border-image: var(--fs-bubble9-cream) 90 fill / 14px round !important;
  padding: 0 4px !important; max-width: 78%;
}
body.fs-scrapbook .msg-bubble.sent { border-image-source: var(--fs-bubble9-pink) !important; }
body.fs-scrapbook .msg-chat-input {
  background: var(--fs-bar9-soft) center top / 100% 100% no-repeat !important;
  padding-top: 14px !important; border: 0 !important;
}
body.fs-scrapbook #msgInput {
  background: transparent !important; border: 12px solid transparent !important; border-radius: 0 !important;
  border-image: var(--fs-field9-soft) 80 fill / 14px round !important; box-shadow: none !important;
}
body.fs-scrapbook #sendMsgBtn {
  background: var(--fs-send-circle) center / contain no-repeat !important;
  border: 0 !important; box-shadow: none !important; color: #fff !important;
}
body.fs-scrapbook .msg-media-btn { background: none !important; color: var(--fs-ink) !important; border: 0 !important; }
body.fs-scrapbook .msg-chat::before { background-image: var(--fs-heart-doodle) !important; }

/* ================================================================
   SCRAPBOOK POSTS — layered like the concept, and each post a little different (data-fs-v 1-6)
   backing paper (9-slice) · torn scrap across the top (::before) · corner tape (::after)
   · photo on a soft mat with tape over its corner · light strip behind the action row
   ================================================================ */
body.fs-scrapbook .feed-post {
  position: relative; overflow: visible !important;
  border-image-source: var(--fs-backing9-aged) !important;
  border-image-slice: 128 fill !important;
  padding-top: 18px !important;
}
body.fs-scrapbook .feed-post::before {   /* torn scrap across the top */
  content: ""; position: absolute; left: -6px; right: -6px; top: -16px; height: 28px;
  background: var(--fs-scrap-pink) center / 100% 100% no-repeat;
  transform: rotate(-0.6deg); z-index: 2; pointer-events: none;
}
body.fs-scrapbook .feed-post::after {    /* tape on the backing's corner */
  content: ""; position: absolute; right: 18px; top: -20px; width: 78px; height: 24px;
  background: var(--fs-tape-beige) center / 100% 100% no-repeat;
  transform: rotate(8deg); z-index: 3; pointer-events: none;
}
body.fs-scrapbook .post-media-grid .pm-thumb::before {   /* tape over the photo's top-left corner */
  display: block !important; content: ""; position: absolute; left: -16px; top: -6px;
  width: 70px; height: 22px; background: var(--fs-tape-beige) center / 100% 100% no-repeat;
  transform: rotate(-32deg); z-index: 3; pointer-events: none;
}
body.fs-scrapbook .post-actions {
  border: 8px solid transparent !important;
  border-image: var(--fs-action-strip9) 80 fill / 10px round !important;
  margin-top: 6px !important;
}
/* the stickers / flowers shown on the photo (grid ::after / ::before) change per look; default none */
body.fs-scrapbook .post-media-grid::after, body.fs-scrapbook .post-media-grid::before { background-image: none !important; }

/* the six looks */
body.fs-scrapbook .feed-post[data-fs-v="1"] { transform: rotate(-0.5deg); }
body.fs-scrapbook .feed-post[data-fs-v="1"] .post-media-grid::after { background-image: var(--fs-heart-sticker) !important; }

body.fs-scrapbook .feed-post[data-fs-v="2"] { transform: rotate(0.5deg); }
body.fs-scrapbook .feed-post[data-fs-v="2"]::before { background-image: var(--fs-scrap-kraft); transform: rotate(0.8deg); }
body.fs-scrapbook .feed-post[data-fs-v="2"]::after { background-image: var(--fs-tape-pink-grid); right: auto; left: 22px; transform: rotate(-9deg); }
body.fs-scrapbook .feed-post[data-fs-v="2"] .pm-thumb::before { background-image: var(--fs-tape-pink-grid); }
body.fs-scrapbook .feed-post[data-fs-v="2"] .post-media-grid::after {
  background-image: var(--fs-sticker-daisy) !important; width: 44px !important; height: 44px !important;
}

body.fs-scrapbook .feed-post[data-fs-v="3"] { transform: rotate(-0.25deg); }
body.fs-scrapbook .feed-post[data-fs-v="3"]::before { background-image: var(--fs-scrap-blue); }
body.fs-scrapbook .feed-post[data-fs-v="3"]::after { background-image: var(--fs-tape-sage); }
body.fs-scrapbook .feed-post[data-fs-v="3"] .pm-thumb::before { background-image: var(--fs-tape-sage); }
body.fs-scrapbook .feed-post[data-fs-v="3"] .post-media-grid::after {
  background-image: var(--fs-sticker-stamp) !important; width: 40px !important; height: 48px !important;
}

body.fs-scrapbook .feed-post[data-fs-v="4"] { border-image-source: var(--fs-backing9-ledger) !important; transform: rotate(0.3deg); }
body.fs-scrapbook .feed-post[data-fs-v="4"] .post-media-grid::before { background-image: var(--fs-flowers-spray) !important; }

body.fs-scrapbook .feed-post[data-fs-v="5"] { transform: rotate(0.7deg); }
body.fs-scrapbook .feed-post[data-fs-v="5"]::before { background-image: var(--fs-scrap-kraft); }
body.fs-scrapbook .feed-post[data-fs-v="5"]::after { background-image: var(--fs-tape-2); right: auto; left: 30px; transform: rotate(-6deg); }
body.fs-scrapbook .feed-post[data-fs-v="5"] .pm-thumb::before { background-image: var(--fs-tape-2); }

body.fs-scrapbook .feed-post[data-fs-v="6"] { border-image-source: var(--fs-backing9-ledger) !important; transform: rotate(-0.6deg); }
body.fs-scrapbook .feed-post[data-fs-v="6"]::before { background-image: var(--fs-scrap-blue); transform: rotate(-1deg); }
body.fs-scrapbook .feed-post[data-fs-v="6"]::after { background-image: var(--fs-tape-pink-grid); }
body.fs-scrapbook .feed-post[data-fs-v="6"] .post-media-grid::after { background-image: var(--fs-heart-sticker) !important; }
/* avatars in the paper ring (concept: chat header, message rows, post headers) */
body.fs-scrapbook .msg-chat-header img,
body.fs-scrapbook .msg-contact > img,
body.fs-scrapbook .post-header img.post-avatar {
  padding: 3px !important; box-sizing: border-box;
  background: var(--fs-avatar-ring) center / contain no-repeat !important;
  border: 0 !important;
}
/* skin cards: the photo frame's border must sit inside the card (was spilling past it and under the name) */
body.fs .fsk-thumb { box-sizing: border-box; width: 100%; }
body.fs-scrapbook .fsk-name { margin-top: 4px !important; }

/* ---------- owner review on a phone ---------- */
/* Home on phones keeps the cover polaroids, profile picture and profile card at the top
   (owner, Nov 15: wanted them back after they were hidden to match the concept) */
/* name + status/bio in one paper label (.fs-namecard, wrapped by the engine) — replaces the old
   negative-margin overlap, which broke at some font sizes */
body.fs-scrapbook .fs-namecard {
  width: 78%; margin: 12px auto 14px; padding: 4px 8px 8px; text-align: center;
  border: 14px solid transparent; border-image: var(--fs-label9) 70 fill / 14px round;
  order: 0;
}
body.fs-scrapbook .fs-namecard > .profile-name {
  border: 0 !important; border-image: none !important; background: none !important;
  width: auto !important; margin: 0 !important; padding: 0 !important; display: block;
}
body.fs-scrapbook .fs-namecard > .profile-title,
body.fs-scrapbook .fs-namecard > .profile-about { margin: 2px 0 0 !important; position: static !important; }
/* stats: no grey tap/hover box */
body.fs .stat, body.fs .stat:hover, body.fs .stat:active, body.fs .stat-clickable:hover { background: none !important; }
body.fs .stat { -webkit-tap-highlight-color: transparent; }
/* paperclip below the status bar, not in it */
body.fs-scrapbook .navbar::before { top: calc(env(safe-area-inset-top, 0px) + 4px) !important; }
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .profile-info > .fs-namecard { order: 0 !important; }
/* the polaroids replace the cover photo, and each has its own camera badge, so the app's separate
   "change cover photo" button is redundant under Scrapbook */
body.fs-scrapbook #coverEditBtn,
body.fs-scrapbook #pvCoverEditBtn { display: none !important; }
@media (max-width: 768px) {
  /* the app pulls the composer 12px past both edges on phones; keep it in line with the other cards */
  body.fs-scrapbook #openPostModal { margin-left: 0 !important; margin-right: 0 !important; }
  body.fs-scrapbook #page-home .main-container { padding-top: 4px !important; }
}
/* spiral binding: rings loop out from the card's left edge (art flipped), not over the quest icons */
body.fs-scrapbook .quest-panel::before {
  left: -24px !important; width: 34px !important;
  transform: scaleX(-1);
}
body.fs-scrapbook .quest-panel { padding-left: 14px !important; }
/* My Profile popup: torn paper dividers instead of thick CSS lines */
body.fs-scrapbook .modal-profile-stats {
  border-color: transparent !important;
  background: var(--fs-divider) center top / 92% 5px no-repeat, var(--fs-divider) center bottom / 92% 5px no-repeat !important;
}
/* the name inside .fs-namecard is plain text (the card is the label); beats the older name-label rule */
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .fs-namecard > .profile-name {
  border: 0 !important; border-image: none !important; background: none !important;
  width: auto !important; margin: 0 !important; padding: 0 !important;
}
body.fs-scrapbook :is(.pv-profile-card, #profileCard) .fs-namecard > :is(.profile-title, .profile-about) {
  margin: 0 !important; position: static !important;
}

/* banner v2 — collage of torn scraps like the master's Home header; shorter, icons smaller and closer */
body.fs-scrapbook .navbar {
  background: var(--fs-banner-collage) center bottom / 100% 100% no-repeat !important;
  height: calc(58px + env(safe-area-inset-top, 0px)) !important;
  max-height: calc(58px + env(safe-area-inset-top, 0px)) !important;
}
@media (max-width: 768px) {
  body.fs-scrapbook #page-home.page.active { padding-top: calc(62px + env(safe-area-inset-top, 0px)) !important; }
  body.fs-scrapbook .navbar .nav-logo { font-size: 24px !important; padding-left: 14px !important; }
  body.fs-scrapbook .navbar .nav-right { gap: 6px !important; }
  body.fs-scrapbook .navbar .mobile-search-btn > i,
  body.fs-scrapbook .navbar .mobile-notif-btn > i,
  body.fs-scrapbook .navbar .nav-music-btn > i { width: 22px !important; height: 22px !important; }
  body.fs-scrapbook .navbar .nav-avatar { width: 34px !important; height: 34px !important; }
  body.fs-scrapbook .nav-user::after { width: 42px !important; height: 42px !important; }
}
body.fs-scrapbook .nav-coins {
  border: 6px solid transparent !important;
  border-image: var(--fs-coin-tag-small) 50 fill / 8px round !important;
  padding: 0 6px !important; font-size: 14px !important; min-height: 0 !important;
}
body.fs-scrapbook .nav-coins > i { width: 20px !important; height: 18px !important; }

/* ================================================================
   POSTS — owner review Nov 15: photos taped straight onto the card (no mat gap),
   shared posts stay inside their paper, action row fits and the liked thumb goes solid
   ================================================================ */
/* the photo fills its box; a thin deckled paper edge hugs it (art drawn over the photo's rim, no fill) */
body.fs-scrapbook .post-media-grid .pm-thumb {
  border: 0 !important;
  border-image: var(--fs-photo-edge9) 30 / 6px / 3px round !important;
}
/* single photo: the row must be the grid's height or a tall photo spills out the bottom */
body.fs-scrapbook .post-media-grid.pm-count-1 { grid-template-rows: minmax(0, 1fr) !important; }
body.fs-scrapbook .post-media-grid.pm-count-1 .pm-thumb { min-height: 0 !important; height: 100% !important; }
body.fs-scrapbook .post-media-grid .pm-thumb img,
body.fs-scrapbook .post-media-grid .pm-thumb video { height: 100% !important; max-height: none !important; object-fit: cover !important; }

/* shared post: a lighter paper card inside the post instead of the app's outlined box */
body.fs-scrapbook .share-preview {
  margin: 4px 0 12px !important;
  background: none !important;
  border: 12px solid transparent !important;
  border-radius: 0 !important;
  border-image: var(--fs-card9-soft) 128 fill / 14px round !important;
  padding: 2px 4px !important;
  overflow: hidden;
}
body.fs-scrapbook .share-preview .post-media-grid::after,
body.fs-scrapbook .share-preview .post-media-grid::before { display: none !important; }

/* action row: six buttons share the width instead of running off the right edge */
body.fs-scrapbook .post-actions { flex-wrap: wrap !important; padding: 2px 2px 0 !important; }
body.fs-scrapbook .post-actions .action-left {
  width: 100%; min-width: 0; gap: 0 !important; flex-wrap: nowrap !important; justify-content: space-between !important;
}
body.fs-scrapbook .post-actions .action-btn {
  min-width: 0; padding: 4px 2px !important; gap: 3px !important; font-size: 14px !important;
  display: inline-flex; align-items: center; white-space: nowrap;
}
body.fs-scrapbook .post-actions .action-btn > i { width: 1.35em !important; height: 1.35em !important; font-size: 15px; }
body.fs-scrapbook .post-actions .view-count-btn > i.fa-eye {
  display: inline-block; background: var(--fs-icon-eye) center / contain no-repeat; color: transparent !important;
