  html body.fs.fs-vaporwave .navbar :is(.nav-left, .nav-right) { display: contents !important; }
  html body.fs.fs-vaporwave .navbar .nav-logo { grid-column: 1 / 6; grid-row: 1; justify-self: start; width: 170px; height: 44px; font-size: 0 !important; color: transparent !important;
