  html body.fs.fs-vaporwave .navbar .nav-avatar { width: 58px !important; height: 58px !important; border-radius: 0 !important; -webkit-mask: none !important; mask: none !important; box-shadow: none !important;
    padding: 13px 3px 3px; box-sizing: border-box; object-fit: cover; background: var(--fs-avatar-window) center / 100% 100% no-repeat !important; }
  html body.fs.fs-vaporwave .navbar :is(.mobile-search-btn, .mobile-notif-btn, .nav-music-btn) { width: 44px !important; height: 34px !important; display: flex !important; align-items: center; justify-content: center;
