  html body.fs.fs-vaporwave .navbar :is(.mobile-search-btn, .mobile-notif-btn, .nav-music-btn) > i { width: 22px !important; height: 22px !important; font-size: 0 !important; background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; }
  html body.fs.fs-vaporwave .navbar .mobile-notif-btn .notif-badge { position: absolute; top: -6px; right: -6px; min-width: 18px; height: 18px; border-radius: 9px; background: var(--fs-badge-count) center / 100% 100% no-repeat !important;
    color: #fff !important; font: 700 11px/18px var(--fs-font) !important; text-align: center; padding: 0 4px; border: 0 !important; }
  html body.fs.fs-vaporwave .navbar .nav-coins { height: 34px !important; padding: 0 10px 0 8px !important; display: flex !important; align-items: center; gap: 5px; margin: 0 !important;
    border: 0 !important; border-image: none !important; border-radius: 0 !important; box-shadow: none !important; background: var(--fs-coin-pill) center / 100% 100% no-repeat !important;
    color: var(--vw-ink) !important; font: 700 15px var(--fs-font) !important; }
