  /* the two switches (OS + light/dark) sit with the bevel buttons */
  html body.fs.fs-vaporwave .navbar .fs-daynight { grid-row: 2; width: 44px; height: 34px; border: 0; padding: 0; background: var(--fs-top-btn) center / 100% 100% no-repeat; display: flex; align-items: center; justify-content: center; }
  html body.fs.fs-vaporwave .navbar .fs-daynight > i { width: 26px; height: 26px; background: center / contain no-repeat; }
  html body.fs.fs-vaporwave .navbar .fs-os-btn.is-retro > i { background-image: var(--fs-toggle-retro); }
  html body.fs.fs-vaporwave .navbar .fs-os-btn.is-modern > i { background-image: var(--fs-toggle-modern); }
  html body.fs.fs-vaporwave .navbar .fs-lamp-btn.is-day > i { background-image: var(--fs-toggle-sun); }
  html body.fs.fs-vaporwave .navbar .fs-lamp-btn.is-night > i { background-image: var(--fs-toggle-moon); }
  html body.fs.fs-vaporwave .nav-container { grid-template-columns: 44px 44px 44px 44px 44px auto 1fr 58px !important; }
  html body.fs.fs-vaporwave .navbar #fsDayNight { grid-column: 1; }
  html body.fs.fs-vaporwave .navbar #fsLamp { grid-column: 2; }
  html body.fs.fs-vaporwave .navbar .mobile-search-btn { grid-column: 3 !important; }
  html body.fs.fs-vaporwave .navbar .mobile-notif-btn { grid-column: 4 !important; }
  html body.fs.fs-vaporwave .navbar .nav-music-wrap { grid-column: 5 !important; }
