  html body.fs.fs-vaporwave .nav-center .nav-link[data-page="profiles"] > i { background-image: var(--fs-icon-network) !important; }
  html body.fs.fs-vaporwave .nav-center .nav-link[data-page="messages"] > i { background-image: var(--fs-icon-messages) !important; }
  html body.fs.fs-vaporwave .nav-center .nav-link .notif-badge { position: absolute; top: 0; right: 2px; }
}

/* ---------- Daily Quests window (concept home) ---------- */
