html body.fs.fs-vaporwave :is(.quest-reward, .quest-check) { background: none !important; color: var(--vw-ink) !important; font: 700 16px var(--fs-font) !important; padding: 0 !important; display: inline-flex; align-items: center; gap: 4px; }
html body.fs.fs-vaporwave .quest-reward > i { font-size: 0 !important; width: 18px; height: 18px; background: var(--fs-coin) center / contain no-repeat; }

