  html body.fs.fs-vaporwave #page-home.active { display: flex !important; flex-direction: column; }
  html body.fs.fs-vaporwave #page-home > .main-container, html body.fs.fs-vaporwave #page-home .left-sidebar { display: contents !important; }
  html body.fs.fs-vaporwave #page-home #profileCard { order: -2; }
  html body.fs.fs-vaporwave #page-home #timelineCover { order: -1; }
