html body.fs.fs-blood-moon .quest-panel { border: 0 !important; border-image: none !important; background: var(--fs-quests-frame) center / 100% 100% no-repeat !important;
  aspect-ratio: 1290 / 900; height: auto !important; box-sizing: border-box; margin: 0 -6px !important;
  padding: 14% 13% 14% 13% !important; align-content: start; row-gap: 2px !important; column-gap: 6px !important; }
html body.fs.fs-blood-moon .quest-panel-header { position: static !important; height: auto !important; top: auto !important; margin: 0 0 2px !important; }
html body.fs.fs-blood-moon .quest-panel-header h4 { font-size: 21px !important; }
html body.fs.fs-blood-moon .quest-item { border: 0 !important; border-image: none !important; background: none !important; padding: 0 !important; }
html body.fs.fs-blood-moon .quest-icon { width: 64px !important; height: 52px !important; }
html body.fs.fs-blood-moon .quest-info p { font-size: 14px !important; line-height: 1.05 !important; }
html body.fs.fs-blood-moon .quest-progress { font-size: 14px !important; }
html body.fs.fs-blood-moon :is(.quest-reward, .quest-check) { font-size: 14px !important; }
html body.fs.fs-blood-moon .quest-reward > i { width: 17px; height: 17px; }
html body.fs.fs-blood-moon .quest-panel { align-content: center !important; padding-top: 12% !important; padding-bottom: 17% !important; }
html body.fs.fs-blood-moon .quest-panel-header { margin-bottom: 8px !important; }
/* spell book layout (owner: nothing should sit on the spine): LEFT page = title, RIGHT page = the three quests listed
   like spellbook entries (constellation · label + progress · coin) */
html body.fs.fs-blood-moon .quest-panel { grid-template-columns: 1fr 1fr !important; grid-auto-flow: row; column-gap: 9% !important; row-gap: 6px !important;
  padding: 13% 12% 15% 12.5% !important; align-content: center !important; align-items: center; }
html body.fs.fs-blood-moon .quest-panel-header { grid-column: 1 !important; grid-row: 1 / span 3 !important; align-self: center; justify-content: center !important; text-align: center; }
html body.fs.fs-blood-moon .quest-panel-header h4 { font-size: 26px !important; line-height: 1.05 !important; text-align: center; white-space: normal; max-width: 6em; margin: 0 auto !important; }
html body.fs.fs-blood-moon .quest-item { grid-column: 2 !important; display: grid !important; grid-template-columns: 34px minmax(0, 1fr); column-gap: 6px; align-items: center; text-align: left !important; }
html body.fs.fs-blood-moon .quest-icon { grid-column: 1; grid-row: 1 / span 2; width: 34px !important; height: 30px !important; margin: 0 !important; }
html body.fs.fs-blood-moon .quest-info { grid-column: 2; align-items: flex-start !important; text-align: left; }
html body.fs.fs-blood-moon .quest-info p { font-size: 13px !important; text-align: left !important; }
html body.fs.fs-blood-moon .quest-progress { font-size: 12px !important; }
html body.fs.fs-blood-moon :is(.quest-reward, .quest-check) { grid-column: 2; justify-self: start; font-size: 12px !important; }
html body.fs.fs-blood-moon .quest-reward > i { width: 14px; height: 14px; }
/* post action row: counts never wrap (view count broke into two lines) */
html body.fs.fs-blood-moon .post-actions { flex-wrap: nowrap !important; gap: 2px !important; padding: 0 2px !important; }
html body.fs.fs-blood-moon .post-actions .action-btn { white-space: nowrap !important; font-size: 15px !important; gap: 4px !important; padding: 4px 2px !important; min-width: 0; }
html body.fs.fs-blood-moon .post-actions .action-btn > i { width: 22px !important; height: 22px !important; }
/* owner: thicker gold around post photos — draw the frame art larger (corners + rims scale up together) */
html body.fs.fs-blood-moon .post-media-grid[class*="pm-count"] .pm-thumb::after { inset: -12px !important; border-width: 64px 80px !important; }
html body.fs.fs-blood-moon .post-media-grid[class*="pm-count"] .pm-thumb { margin: 14px 10px !important; }
html body.fs.fs-blood-moon .post-media-grid[class*="pm-count"] .pm-thumb::before { top: -28px !important; width: 110px !important; height: 44px !important; }
/* bar labels/icons are buttons, never selectable text (a long-press popped the iOS copy menu) */
html body.fs :is(.nav-center, .navbar, .mobile-pills-bar, .search-tabs) { -webkit-user-select: none !important; user-select: none !important; -webkit-touch-callout: none !important; }
/* Photos card fit inside the screen */
html body.fs.fs-blood-moon .photos-card { margin-left: 0 !important; margin-right: 0 !important; width: auto !important; max-width: 100% !important; box-sizing: border-box; }
/* post card v3 (iridescent + ornate gold, 140px corners) and thicker photo frame (210x160 corners) */
html body.fs.fs-blood-moon .feed-post.feed-post.feed-post { border-width: 34px !important; border-image: var(--fs-post-panel) 140 fill / 34px stretch !important; }
html body.fs.fs-blood-moon .post-media-grid[class*="pm-count"] .pm-thumb::after { border-image: var(--fs-photo-frame) 160 210 / 50px 64px stretch !important; border-width: 50px 64px !important; inset: -10px !important; }
/* owner: same square card, gold rim as thick as Witchcraft's — draw the frame art larger (rim ~1.8x) and push it
   outward with an outset so the post content keeps its room */
html body.fs.fs-blood-moon .feed-post.feed-post.feed-post { border-width: 34px !important; border-image-source: var(--fs-post-panel) !important;
  border-image-slice: 140 fill !important; border-image-width: 62px !important; border-image-outset: 12px !important; border-image-repeat: stretch !important;
  margin-left: 12px !important; margin-right: 12px !important; margin-bottom: 26px !important; }
/* shared-post box: slice must contain the whole corner ornament (art corners ~175x110) or the vines smear down the sides */
html body.fs.fs-blood-moon .share-preview { border-width: 24px 34px !important; border-image: var(--fs-comment-bubble) 115 180 fill / 24px 34px stretch !important; padding: 2px 0 !important; }
html body.fs.fs-blood-moon .comment-item { border-width: 24px 34px !important; border-image: var(--fs-comment-bubble) 115 180 fill / 24px 34px stretch !important; }
/* cat-on-cloud: never tucked under the button (its ear and the crystal tips were cut off) */
html body.fs.fs-blood-moon :is(#profileCard, .pv-profile-card)::after { margin: 10px -8px 0 !important; padding-bottom: 34% !important; background-size: 92% auto !important; background-position: center top !important; position: relative; z-index: 0; }
/* themed sun / moon art on the Day/Night toggle (Good Witch) */
/* enchanted charms around posts (owner: "like the scrapbook, place unused assets around the posts"): each post gets one of
   six looks (data-fs-v 1-6, stable per post) — a charm perched on a corner of the gold frame, never over the content */
html body.fs.fs-blood-moon .feed-post { position: relative; overflow: visible !important; }
html body.fs.fs-blood-moon .feed-post::after { content: ""; position: absolute; pointer-events: none; z-index: 4; background: center / contain no-repeat; }
html body.fs.fs-blood-moon .feed-post[data-fs-v="1"]::after { right: -26px; bottom: -40px; width: 104px; height: 90px; background-image: var(--fs-page-deco-post); }
html body.fs.fs-blood-moon .feed-post[data-fs-v="2"]::after { left: -30px; top: -34px; width: 100px; height: 84px; background-image: var(--fs-curtain-left); }
html body.fs.fs-blood-moon .feed-post[data-fs-v="3"]::after { right: -14px; top: -26px; width: 56px; height: 56px; background-image: var(--fs-moon-crest); transform: rotate(12deg); }
html body.fs.fs-blood-moon .feed-post[data-fs-v="4"]::after { right: -30px; top: -34px; width: 100px; height: 84px; background-image: var(--fs-curtain-right); }
html body.fs.fs-blood-moon .feed-post[data-fs-v="5"]::after { left: -18px; bottom: -30px; width: 84px; height: 72px; background-image: var(--fs-moon-100); transform: rotate(-10deg); }
html body.fs.fs-blood-moon .feed-post[data-fs-v="6"]::after { left: 50%; bottom: -32px; width: 150px; height: 44px; margin-left: -75px; background-image: var(--fs-moon-crest); }
/* a second, smaller sparkle on alternate looks */
html body.fs.fs-blood-moon .feed-post:is([data-fs-v="1"], [data-fs-v="4"]) .post-header { position: relative; }
html body.fs.fs-blood-moon .feed-post:is([data-fs-v="1"], [data-fs-v="4"]) .post-header::before { content: ""; position: absolute; left: -32px; top: -30px; width: 46px; height: 46px; pointer-events: none;
  background: var(--fs-moon-crest) center / contain no-repeat; opacity: .9; }
/* keep posts far enough apart that the charms never collide */
html body.fs.fs-blood-moon .feed-post.feed-post.feed-post { margin-bottom: 40px !important; }
/* vines reached into the post (over the avatar) — use edge-sitting charms instead */
html body.fs.fs-blood-moon .feed-post[data-fs-v="2"]::after { left: 50%; top: -30px; right: auto; bottom: auto; width: 120px; height: 48px; margin-left: -60px; background-image: var(--fs-moon-crest); transform: none; }
html body.fs.fs-blood-moon .feed-post[data-fs-v="4"]::after { right: -20px; top: -30px; left: auto; bottom: auto; width: 82px; height: 70px; background-image: var(--fs-moon-100); transform: rotate(14deg); }
html body.fs.fs-blood-moon .feed-post:is([data-fs-v="1"], [data-fs-v="4"]) .post-header::before { left: -44px !important; top: -42px !important; width: 40px !important; height: 40px !important; }
/* owner: golden ornaments around the round pictures — ornate gold ring (window 84%, inset 8%) on the cover bubbles + avatar */
html body.fs.fs-blood-moon .fs-tl-slot::before { inset: -4% !important; background-image: var(--fs-photo-frame) !important; }
html body.fs.fs-blood-moon .fs-tl-slot img { inset: 4% !important; width: 92% !important; height: 92% !important; }
html body.fs.fs-blood-moon :is(.pv-profile-card, #profileCard) .profile-avatar-wrap::after { inset: -9% !important; background-image: var(--fs-photo-frame) !important; }
/* ===== QA pass (owner: "not all sized correctly") ===== */
/* skin cards: ornate frame as a 9-slice around the whole card (whole-image stretch put the window in the wrong place
   and the art spilled past the frame); the card art sits inside with rounded corners */
html body.fs.fs-blood-moon .fsk-card { background: none !important; border: solid transparent !important; border-width: 22px 26px !important;
  border-image: var(--fs-comment-bubble) 115 180 fill / 22px 26px stretch !important; padding: 0 0 4px !important; overflow: hidden !important; box-sizing: border-box; }
html body.fs.fs-blood-moon .fsk-thumb { margin: 0 !important; width: 100% !important; aspect-ratio: 4 / 3 !important; border-radius: 10px !important; overflow: hidden !important;
  box-shadow: 0 0 0 2px rgba(201, 163, 92, .85) !important; }
html body.fs.fs-blood-moon .fsk-body { padding: 6px 2px 0 !important; }
html body.fs.fs-blood-moon .fsk-name { font-size: 17px !important; text-align: center !important; }
html body.fs.fs-blood-moon .fsk-badge { top: 6px !important; right: 6px !important; }
html body.fs.fs-blood-moon .fsk-color { outline: none !important; box-shadow: 0 0 0 2px rgba(201, 163, 92, .7) !important; }
html body.fs.fs-blood-moon .fsk-color.is-on { box-shadow: 0 0 0 2px #fff, 0 0 0 4px #c9a35c !important; }
html body.fs.fs-blood-moon .fsk-body .btn { height: 40px !important; font-size: 15px !important; }
html body.fs.fs-blood-moon :is(.fsk-soon, .fsk-takeoff) { font-size: 14px !important; }
/* chips / filter buttons: 9-slice so the end curls keep their shape on long labels */
html body.fs.fs-blood-moon :is(#groupsTabs, #shopTabs, #mySkinsTabs, #skinPageToggle, #notifTabs, #gvModeTabs) .search-tab, html body.fs.fs-blood-moon .fsk-filter {
  background: none !important; border: solid transparent !important; border-width: 10px 18px !important; border-image: var(--fs-chip) 55 85 fill / 10px 18px stretch !important;
  padding: 2px 4px !important; font-size: 15px !important; min-height: 0 !important; }
html body.fs.fs-blood-moon :is(#groupsTabs, #shopTabs, #mySkinsTabs, #skinPageToggle, #notifTabs, #gvModeTabs) .search-tab.active, html body.fs.fs-blood-moon .fsk-filter.active { border-image-source: var(--fs-chip-active) !important; }
html body.fs.fs-blood-moon :is(#groupsTabs, #shopTabs, #mySkinsTabs, #skinPageToggle, #notifTabs, #gvModeTabs) .search-tab.search-tab, html body.fs.fs-blood-moon .fsk-filter.fsk-filter {
  background-image: none !important; background-color: transparent !important; box-shadow: none !important; border-width: 7px 14px !important; font-size: 14px !important; padding: 1px 2px !important; line-height: 1.2 !important; }
html body.fs.fs-blood-moon :is(#groupsTabs, #shopTabs, #mySkinsTabs, #skinPageToggle, #notifTabs, #gvModeTabs) { gap: 6px !important; margin: 4px 0 !important; }
html body.fs.fs-blood-moon .fsk-badge { background-color: transparent !important; box-shadow: none !important; }
/* list rows (network/search/groups/messages/notifications): 9-slice matched to the art's corners, compact sizes */
html body.fs.fs-blood-moon :is(.msg-contact, .notif-item, .profile-card-item, .follow-list-item, #groupsSections .group-card) {
  border-width: 16px 24px !important; border-image: var(--fs-list-row) 95 150 fill / 16px 24px stretch !important; padding: 0 !important; margin: 0 0 8px !important; }
html body.fs.fs-blood-moon :is(#page-profiles, #page-search) .profile-card-item { grid-template-columns: 50px minmax(0, 1fr) auto !important; column-gap: 10px !important; }
html body.fs.fs-blood-moon :is(#page-profiles, #page-search) .profile-card-avatar { width: 50px !important; height: 50px !important; }
html body.fs.fs-blood-moon :is(#page-profiles, #page-search) .profile-card-name { font-size: 17px !important; }
html body.fs.fs-blood-moon :is(#page-profiles, #page-search) .profile-card-bio { font-size: 13px !important; }
/* Join / Follow plaques: 9-slice so the heart + sparkle ends keep their size, words stay in the middle */
html body.fs.fs-blood-moon :is(.join-group-btn, .suggestion-follow-btn, .follow-btn, .profile-follow-btn, #groupsSections .group-card-actions .btn) {
  background: none !important; border: solid transparent !important; border-width: 9px 16px !important; border-image: var(--fs-join-btn) 60 95 fill / 9px 16px stretch !important;
  height: auto !important; min-width: 0 !important; padding: 2px 2px !important; font-size: 14px !important; line-height: 1.2 !important; white-space: nowrap; }
html body.fs.fs-blood-moon #groupsSections .group-card-actions .btn .gc-btn-text { font-size: 14px !important; }
/* segmented tabs: smaller labels so two-line tabs fit */
html body.fs.fs-blood-moon :is(#profilesTabs, #searchTabs) .search-tab { font-size: 13px !important; min-height: 40px !important; padding: 2px 6px !important; background: none !important;
  border: solid transparent !important; border-width: 8px 16px !important; border-image: var(--fs-seg-tab) 55 90 fill / 8px 16px stretch !important; }
html body.fs.fs-blood-moon :is(#profilesTabs, #searchTabs) .search-tab.active { border-image-source: var(--fs-seg-tab-active) !important; }
/* section headers + count badge */
html body.fs.fs-blood-moon :is(#page-profiles, #page-search) :is(h3, .section-title) { font-size: 17px !important; }
html body.fs.fs-blood-moon :is(.section-count, .connections-count, .badge-count) { background: rgba(255,255,255,.18) !important; border: 1px solid rgba(201,163,92,.7) !important; color: var(--bm-title) !important; }
/* skin-option toggle for colour skins (Anime Blaze): current colour as a jewel; tap = next colour */
html body.fs .fs-swatch-btn { width: 34px; height: 34px; margin: 0 2px; flex: 0 0 auto; }
html body.fs .fs-swatch-btn i { display: block; width: 22px; height: 22px; border-radius: 50%; font-size: 0;
  background: radial-gradient(circle at 35% 30%, rgba(255,255,255,.75), transparent 45%), var(--sw);
  box-shadow: 0 0 0 2px #fff, 0 0 0 3.5px #111, 0 0 10px var(--sw); }
/* Anime Blaze colour swap button press */
html body.fs-anime-blaze .fs-swatch-btn:active i { transform: scale(.85); }
/* Anime Blaze skin cards (owner, Nov 15: all previews the same size, no colour dots): name on top, one compact
   button under it, both inside the dark band so the button never covers the name */
html body.fs.fs-anime-blaze .fsk-body { top: 65.5% !important; height: 25% !important; justify-content: flex-start !important; gap: 4px !important; }
html body.fs.fs-anime-blaze .fsk-name { flex: 0 0 auto; line-height: 1.2 !important; padding-top: 1px; }
html body.fs.fs-anime-blaze .fsk-body .btn:not(.fsk-equipped) { flex: 0 0 auto; height: 30px !important; line-height: 1 !important; margin: 0 !important; padding: 0 18px !important;
  border-width: 0 !important; overflow: visible !important;
  font-size: 13px !important; transform: none !important; display: inline-flex !important; align-items: center; }
/* Good Witch skin cards all the same size (owner, Nov 15): the picture's "Equipped" tag already says it, so the
   equipped card shows one button — Take off — in the place the other cards show Equip/Buy */
html body.fs.fs-blood-moon .fsk-body .btn.fsk-equipped { display: none !important; }
html body.fs.fs-blood-moon .fsk-body .fsk-takeoff { width: 100% !important; height: 40px !important; margin: 6px 0 0 !important; padding: 0 10px !important;
  display: flex !important; align-items: center; justify-content: center; border: 0 !important; border-radius: 0 !important; box-shadow: none !important;
  background: var(--fs-join-btn) center / 100% 100% no-repeat !important; color: var(--bm-title) !important; font: 700 15px var(--fs-font) !important; text-decoration: none !important; }
/* Good Witch Messages (QA Nov 15): search field the same width as the rows below it, with a gap before the first row */
html body.fs.fs-blood-moon #page-messages .msg-search { margin: 0 7px 12px !important; }
/* notifications (QA Nov 15): the expand arrow lines up on the right edge of every row, not right after the text */
html body.fs .notif-text p .notif-expand-chevron { margin-left: auto !important; padding-left: 8px; flex: 0 0 auto; }
/* Good Witch Search (QA Nov 15): People / Groups / Posts as the same gold chips as Notifications, centred */
html body.fs.fs-blood-moon #page-search .search-tabs { display: flex !important; justify-content: center; gap: 8px; border: 0 !important; background: none !important; padding: 2px 0 !important; }
html body.fs.fs-blood-moon #page-search .search-tab { flex: 0 0 auto; background: none !important; border: solid transparent !important; border-width: 10px 18px !important;
  border-image: var(--fs-chip) 55 85 fill / 10px 18px stretch !important; border-radius: 0 !important; box-shadow: none !important;
  padding: 2px 6px !important; font-size: 15px !important; min-height: 0 !important; color: var(--bm-title) !important; }
html body.fs.fs-blood-moon #page-search .search-tab.active { border-image-source: var(--fs-chip-active) !important; color: var(--bm-deep) !important; font-weight: 700 !important; }
html body.fs.fs-blood-moon #searchResults .search-results-grid { gap: 0 !important; margin-top: 8px; }
/* Good Witch Groups (QA Nov 15): the phone layout squeezes group buttons into 40px circles, which cut "Joined" to "n" —
   size the button to its word instead */
html body.fs.fs-blood-moon #groupsSections .group-card-actions .btn { width: auto !important; min-width: 92px !important; height: auto !important; padding: 2px 6px !important; }
/* Good Witch group page (QA Nov 15): name clear of the cover and sized to fit; three stats that fit the frame
   ("Members" no longer splits); Edit / Joined / Leave as the same readable buttons as the group list, in Day and Night */
html body.fs.fs-blood-moon #gvProfileCard .profile-name { font-size: 30px !important; margin: 34px 12px 0 !important; overflow-wrap: anywhere; position: relative; z-index: 2; }
html body.fs.fs-blood-moon #gvProfileCard .profile-stats { padding: 6px 22px !important; width: 96% !important; }
html body.fs.fs-blood-moon #gvProfileCard .stat-count { font-size: 24px !important; }
html body.fs.fs-blood-moon #gvProfileCard .stat-label { font-size: 14px !important; white-space: nowrap; line-height: 1.2 !important; display: block; }
html body.fs.fs-blood-moon #gvProfileCard .stat-label i { margin-right: 3px; font-size: 11px !important; }
html body.fs.fs-blood-moon #gvProfileCard .stat-label { font-size: 13px !important; }
html body.fs.fs-blood-moon #gvProfileCard .pv-actions { display: flex !important; flex-wrap: wrap; justify-content: center; gap: 8px !important; margin-top: 12px !important; }
html body.fs.fs-blood-moon #gvProfileCard .pv-actions .btn { flex: 0 0 auto; width: auto !important; min-width: 110px; height: auto !important; margin: 0 !important; padding: 2px 6px !important;
  background: none !important; border: solid transparent !important; border-width: 9px 16px !important; border-image: var(--fs-join-btn) 60 95 fill / 9px 16px stretch !important;
  border-radius: 0 !important; box-shadow: none !important; color: var(--bm-title) !important; font: 700 15px var(--fs-font) !important; opacity: 1 !important; }
html body.fs.fs-blood-moon #gvProfileCard .pv-actions .btn i { color: inherit !important; margin-right: 4px; }
/* Good Witch comments (QA Nov 15): sort tabs as the gold chips, the comment box on the field art, GIF a small chip,
   Post the same button as everywhere else */
html body.fs.fs-blood-moon .comment-sort-tab { flex: 0 0 auto; background: none !important; border: solid transparent !important; border-width: 9px 16px !important;
  border-image: var(--fs-chip) 55 85 fill / 9px 16px stretch !important; border-radius: 0 !important; box-shadow: none !important;
  padding: 1px 4px !important; font-size: 15px !important; min-height: 0 !important; color: var(--bm-title) !important; margin-right: 6px; }
html body.fs.fs-blood-moon .comment-sort-tab.active { border-image-source: var(--fs-chip-active) !important; color: var(--bm-deep) !important; font-weight: 700 !important; }
html body.fs.fs-blood-moon #commentInput { background: none !important; border: solid transparent !important; border-width: 10px 20px !important;
  border-image: var(--fs-field) 60 130 fill / 10px 20px stretch !important; border-radius: 0 !important; box-shadow: none !important;
  padding: 2px 2px !important; min-height: 0 !important; color: var(--bm-ink) !important; font: 600 16px var(--fs-font) !important; }
html body.fs.fs-blood-moon #commentGifBtn { background: none !important; border: solid transparent !important; border-width: 8px 12px !important;
  border-image: var(--fs-chip) 55 85 fill / 8px 12px stretch !important; border-radius: 0 !important; box-shadow: none !important;
  padding: 0 2px !important; color: var(--bm-title) !important; font: 700 13px var(--fs-font) !important; }
html body.fs.fs-blood-moon #postCommentBtn { flex: 0 0 auto; width: auto !important; height: auto !important; background: none !important; border: solid transparent !important;
  border-width: 9px 16px !important; border-image: var(--fs-join-btn) 60 95 fill / 9px 16px stretch !important; border-radius: 0 !important; box-shadow: none !important;
  padding: 2px 6px !important; color: var(--bm-title) !important; font: 700 15px var(--fs-font) !important; }
/* Good Witch post badges (Shared, location…): the small gold chip, like the other pills (QA Nov 15) */
html body.fs.fs-blood-moon .post-badges :is(span, .post-badge) { background: none !important; border: solid transparent !important; border-width: 7px 12px !important;
  border-image: var(--fs-chip) 55 85 fill / 7px 12px stretch !important; border-radius: 0 !important; padding: 0 2px !important; font-size: 13px !important; line-height: 1.2 !important; }
